import { test, expect } from '@playwright/test';

test.describe('Notification Preferences Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should successfully manage notification preferences', async ({ page }) => {
    // Verify settings page is visible
    const settingsHeader = page.getByRole('heading', { name: /settings/i });
    await expect(settingsHeader).toBeVisible();

    // Navigate to notification settings
    const notificationLink = page.getByRole('link', { name: /notifications/i });
    await expect(notificationLink).toBeVisible();
    await notificationLink.click();

    // Verify notification settings section is displayed
    const notificationSection = page.getByRole('region', { name: /notification preferences/i });
    await expect(notificationSection).toBeVisible();

    // Toggle email notifications on
    const emailToggle = page.getByLabel(/email notifications/i);
    await expect(emailToggle).toBeVisible();
    await emailToggle.click();
    await expect(emailToggle).toHaveAttribute('aria-checked', 'true');

    // Toggle SMS notifications off
    const smsToggle = page.getByLabel(/sms notifications/i);
    await expect(smsToggle).toBeVisible();
    await smsToggle.click();
    await expect(smsToggle).toHaveAttribute('aria-checked', 'false');

    // Toggle push notifications on
    const pushToggle = page.getByLabel(/push notifications/i);
    await expect(pushToggle).toBeVisible();
    await pushToggle.click();
    await expect(pushToggle).toHaveAttribute('aria-checked', 'true');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save preferences/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify success message
    const successMessage = page.getByText(/preferences saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify toggles reflect saved state
    await expect(emailToggle).toHaveAttribute('aria-checked', 'true');
    await expect(smsToggle).toHaveAttribute('aria-checked', 'false');
    await expect(pushToggle).toHaveAttribute('aria-checked', 'true');
  });

  test('should handle invalid email format when saving notification preferences', async ({ page }) => {
    // Navigate to notification settings
    const notificationLink = page.getByRole('link', { name: /notifications/i });
    await expect(notificationLink).toBeVisible();
    await notificationLink.click();

    // Verify notification settings section is displayed
    const notificationSection = page.getByRole('region', { name: /notification preferences/i });
    await expect(notificationSection).toBeVisible();

    // Toggle email notifications on
    const emailToggle = page.getByLabel(/email notifications/i);
    await expect(emailToggle).toBeVisible();
    await emailToggle.click();
    await expect(emailToggle).toHaveAttribute('aria-checked', 'true');

    // Enter invalid email format
    const emailInput = page.getByLabel(/email address/i);
    await expect(emailInput).toBeVisible();
    await emailInput.fill('invalid-email');

    // Attempt to save with invalid email
    const saveButton = page.getByRole('button', { name: /save preferences/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid email format/i);
    await expect(errorMessage).toBeVisible();

    // Verify email input still contains invalid value
    await expect(emailInput).toHaveValue('invalid-email');

    // Verify success message does not appear
    const successMessage = page.getByText(/preferences saved successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Correct the email format
    await emailInput.clear();
    await emailInput.fill('user@example.com');

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify save button is enabled
    await expect(saveButton).toBeEnabled();
  });
});
